  FT["PH-H2493"] = {"id":"PH-H2493","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2766_1960.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在伊莎贝拉省Roxas市镇设立急诊医院，名称为Roxas纪念急诊医院，并授权为此拨款的法案","en":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Roxas, Province of Isabela, to be Known as the Roxas Memorial Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Roxas, Province of Isabela, to be Known as the Roxas Memorial Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Cấp cứu tại Thị trấn Roxas, Tỉnh Isabela với tên gọi Bệnh viện Cấp cứu Tưởng niệm Roxas, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลฉุกเฉินในเทศบาล Roxas จังหวัด Isabela ในชื่อโรงพยาบาลฉุกเฉินอนุสรณ์ Roxas และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Gawat Darurat di Kotamadya Roxas, Provinsi Isabela dengan nama Rumah Sakit Gawat Darurat Memorial Roxas, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Kecemasan di Perbandaran Roxas, Wilayah Isabela dengan nama Hospital Kecemasan Memorial Roxas, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2766","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2766_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2493-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Roxas, Province of Isabela, to be known as the Roxas Memorial Emergency Hospital. The site for the said hospital shall be provided by the Municipal Council of the Municipality of Roxas, in consultation with the Director of Medical Services."}},{"id":"PH-H2493-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall promulgate such rules and regulations as may be necessary to carry into effect the purpose of this Act."}},{"id":"PH-H2493-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum, of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said hospital during the fiscal year nineteen hundred and sixty-one. Such sum as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H2493-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p35","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Roxas, Province of Isabela, to be Known as the Roxas Memorial Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2494"] = {"id":"PH-H2494","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2767_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"更改南三宝颜省Liargao市镇若干村落名称的法案","en":"An Act Changing the Names of Certain Barrios in the Municipality of Liargao, Province of Zamboanga del Sur","orig":"An Act Changing the Names of Certain Barrios in the Municipality of Liargao, Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2767","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2767_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2494-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Sominot in the Municipality of Liargao, Province of Zamboanga del Sur, is changed to Oliva."}},{"id":"PH-H2494-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The name of the barrio of Lower Malating in the same municipality is changed to Magsaysay."}},{"id":"PH-H2494-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p35","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Names of Certain Barrios in the Municipality of Liargao, Province of Zamboanga del Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
