  FT["PH-H2496"] = {"id":"PH-H2496","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2769_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立San Agustin市","en":"An Act Declaring Regular and Official the Barrios of Dabubu Pequeño, Rang-Ay, Sto. Niño, Mapalad, San Antonio, Quimalabasa Norte, Quimalabasa Sur, Panang, Santos, Calaocan and Masaya Centro in the Municipality of San Agustin, Province of Isabela","orig":"An Act Declaring Regular and Official the Barrios of Dabubu Pequeño, Rang-Ay, Sto. Niño, Mapalad, San Antonio, Quimalabasa Norte, Quimalabasa Sur, Panang, Santos, Calaocan and Masaya Centro in the Municipality of San Agustin, Province of Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2769","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2769_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2496-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Dabubu Pequeño, Rang-ay, Sto. Niño, Mapalad, San Antonio, Quimalabasa Norte, Quimalabasa Sur, Panang, Santos, Calaocan and Masaya Centro in the Municipality of San Agustin, Province of Isabela, are hereby declared regular and official barrios thereof."}},{"id":"PH-H2496-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p35"};
