  FT["PH-H2501"] = {"id":"PH-H2501","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2774_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Bayambang市","en":"An Act Creating the Barrio of Bongato West in the Municipality of Bayambang, Province of Pangasinan","orig":"An Act Creating the Barrio of Bongato West in the Municipality of Bayambang, Province of Pangasinan","vi":"Đạo luật thành lập một Barrio Bongato West tại Đô thị Bayambang, Tỉnh Pangasinan","th":"พระราชบัญญัติจัดตั้งบาริโอ Bongato West ในเทศบาล Bayambang จังหวัด Pangasinan","id":"Undang-Undang membentuk sebuah Barrio Bongato West di Kotamadya Bayambang, Provinsi Pangasinan","ms":"Akta menubuhkan sebuah Barrio Bongato West di Perbandaran Bayambang, Wilayah Pangasinan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2774","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2774_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2501-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Bongato West is separated from the Barrio of Bongato, Municipality of Bayambang, Province of Pangasinan, and same is hereby constituted as a distinct and separate barrio of the said municipality."}},{"id":"PH-H2501-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The remaining portion shall be known as Barrio Bongato East."}},{"id":"PH-H2501-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p35"};
