  FT["PH-H2517"] = {"id":"PH-H2517","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2790_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Virac市","en":"An Act Creating Certain Barrios in the Municipality of Virac, Province of Catanduanes","orig":"An Act Creating Certain Barrios in the Municipality of Virac, Province of Catanduanes","vi":"Đạo luật thành lập các Barrio tại Đô thị Virac, Tỉnh Catanduanes","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Virac จังหวัด Catanduanes","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Virac, Provinsi Catanduanes","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Virac, Wilayah Catanduanes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2790","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2790_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2517-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following places in the Municipality of Virac, Province of Catanduanes, are declared as barrios of said municipality, to wit:\n1. Bagui, Pajo as Barrio Bagui, Pajo;\n2. Bigaa as Barrio Bigaa;\n3. Calampong as Barrio Calampong;\n4. Buenavista as Barrio Buenavista;\n5. Capilihan as Barrio Capilihan;\n6. Dugui (TO-O) as Barrio Dugui (TO-O);\n7. Hawan (Ilaya) as Barrio Hawan (Ilaya);\n8. Igang as Barrio Igang;\n9. Palta (Small) as Barrio Palta (Small);\n10. Sto. Cristo (Cabijian) as Barrio Sto. Cristo (Cabijian);\n11. San Isidro (Dugui Wala) as Barrio San Isidro (Dugui Wala);\n12. San Vicente (Dugui Wala) as Barrio San Vicente (Dugui Wala);\n13. San Isidro, Pajo, as Barrio San Isidro, Pajo; and\n14. Valencia as Barrio Valencia."}},{"id":"PH-H2517-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p35"};
  FT["PH-H2518"] = {"id":"PH-H2518","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2791_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉省圣马特奥市镇达古潘、比利亚马加特与圣曼努埃尔村的部分区域组建为名为利加亚村的法案","en":"An Act Constituting Portions of Barrios Dagupan, Villa Magat and San Manuel in the Municipality of San Mateo, Province of Isabela, into a Barrio to be Known as Barrio Ligaya","orig":"An Act Constituting Portions of Barrios Dagupan, Villa Magat and San Manuel in the Municipality of San Mateo, Province of Isabela, into a Barrio to be Known as Barrio Ligaya"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2791","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2791_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2518-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Portions of barrios Dagupan, Villa Magat and San Manuel in the Municipality of San Mateo, Province of Isabela, separated from said barrios by the canal of the Magat River Irrigation System, are constituted into a barrio to be known as Barrio Ligaya."}},{"id":"PH-H2518-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p35","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting Portions of Barrios Dagupan, Villa Magat and San Manuel in the Municipality of San Mateo, Province of Isabela, into a Barrio to be Known as Barrio Ligaya","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
