  FT["PH-H2531"] = {"id":"PH-H2531","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2804_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"变更北三宝颜省 Polanco市镇某村与小村的名称的法案","en":"An Act Changing the Names of Certain Barrios and Sitios in the Municipality of Polanco, Province of Zamboanga del Norte","orig":"An Act Changing the Names of Certain Barrios and Sitios in the Municipality of Polanco, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2804","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2804_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2531-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of the following barrios and sitios in the Municipality of Polanco, Province of Zamboanga del Norte, are changed as follows:\n1. Barrio Prenda to Barrio Labrador;\n2. Barrio Loboc to Barrio San Miguel;\n3. Sitio Lantoy to Sitio Sto. Niño;\n4. Sitio Biga-an to Sitio Mabuhay; and\n5. Sitio Ludloron to Sitio Salvador."}},{"id":"PH-H2531-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p35","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Names of Certain Barrios and Sitios in the Municipality of Polanco, Province of Zamboanga del Norte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
